mapper.select:
SELECT *
FROM chat_rooms

    AND last_message_id IS NOT NULL


        AND response_status = #{responseStatus}


ORDER BY updated_at DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM chat_rooms
AND last_message_id IS NOT NULL
AND response_status = #{responseStatus}

SELECT COUNT(*)
FROM chat_messages
WHERE chat_room_id = #{chatRoomId}
  AND id > #{lastReadMessageId}
  AND sender_id = #{customerId}

SELECT m.chat_room_id AS chatRoomId, COUNT(*) AS unreadCount FROM chat_messages m INNER JOIN chat_rooms r ON m.chat_room_id = r.id LEFT JOIN chat_room_read_cursors c ON c.chat_room_id = r.id AND c.reader_side = 'ADMIN' WHERE r.id IN
#{roomId}
AND m.sender_id = r.customer_id AND m.id > COALESCE(c.last_read_message_id, 0) GROUP BY m.chat_room_id

SELECT *
FROM (
    SELECT *
    FROM chat_messages
    WHERE chat_room_id = #{chatRoomId}
    ORDER BY created_at DESC, id DESC
    LIMIT #{size} OFFSET #{offset}
) sub
ORDER BY created_at ASC, id ASC

SELECT * FROM chat_message_attachments WHERE chat_message_id IN
#{msgId}
ORDER BY chat_message_id ASC, display_order ASC, id ASC

SELECT *
FROM chat_room_read_cursors
WHERE chat_room_id = #{chatRoomId}
  AND reader_side = #{readerSide}
